onent  -->\n\nBibliographyModule->BibliographyComponent \n\n\n\n\n\nBibliographyDetailComponent \n\nBibliographyDetailComponent \n\nBibliographyDetailComponent  -->\n\nBibliographyModule->BibliographyDetailComponent \n\n\n\n\n\nBibliographyFormatPipe \n\nBibliographyFormatPipe \n\nBibliographyFormatPipe  -->\n\nBibliographyModule->BibliographyFormatPipe \n\n\n\n\n\nBibliographyListComponent \n\nBibliographyListComponent \n\nBibliographyListComponent  -->\n\nBibliographyModule->BibliographyListComponent \n\n\n\n\n\nBibliographySearchComponent \n\nBibliographySearchComponent \n\nBibliographySearchComponent  -->\n\nBibliographyModule->BibliographySearchComponent \n\n\n\n\n\nBibliographyRoutingModule\n\nBibliographyRoutingModule\n\nBibliographyModule -->\n\nBibliographyRoutingModule->BibliographyModule\n\n\n\n\n\nSharedModule\n\nSharedModule\n\nBibliographyModule -->\n\nSharedModule->BibliographyModule\n\n\n\n\n\n\n    \n    \n    \n        Zoom in\n        Reset\n        Zoom out\n    \n\n\n\n\n\n    \n        Info\n    \n    \n        Source\n    \n\n\n\n    \n\n        \n            File\n        \n        \n            src/app/views/data-view/data-outlets/bibliography/bibliography.module.ts\n        \n\n\n\n        \n            Description\n        \n        \n            The bibliography module.\nIt embeds the bibliography components and their routing definition,\nthe BibliographySearchComponent, BibliographyListComponent, BibliographyFormatPipe\nas well as the SharedModule.\n\n        \n\n\n        \n            \n                \n                    Declarations\n                    \n                        \n                            BibliographyComponent\n                        \n                        \n                            BibliographyDetailComponent\n                        \n                        \n                            BibliographyFormatPipe\n                        \n                        \n                            BibliographyListComponent\n                        \n                        \n                            BibliographySearchComponent\n                        \n                    \n                \n                \n                    Imports\n                    \n                        \n                            BibliographyRoutingModule\n                        \n                        \n                            SharedModule\n                        \n                    \n                \n                \n                    Exports\n                    \n                        \n                            BibliographyComponent\n                        \n                        \n                            BibliographyDetailComponent\n                        \n                        \n                            BibliographyFormatPipe\n                        \n                        \n                            BibliographyListComponent\n                        \n                        \n                            BibliographySearchComponent\n                        \n                    \n                \n            \n        \n\n\n    \n\n\n    \n        import { NgModule } from '@angular/core';\nimport { SharedModule } from '@awg-shared/shared.module';\n\nimport { BibliographyFormatPipe } from './bibliography-format.pipe';\nimport { BibliographyListComponent } from './bibliography-list/bibliography-list.component';\nimport { BibliographySearchComponent } from './bibliography-search/bibliography-search.component';\n\n/* Routing Module */\nimport { BibliographyRoutingModule, routedBibliographyComponents } from './bibliography-routing.module';\n\n/**\n * The bibliography module.\n *\n * It embeds the bibliography components and their [routing definition]{@link BibliographyRoutingModule},\n * the {@link BibliographySearchComponent}, {@link BibliographyListComponent}, {@link BibliographyFormatPipe}\n * as well as the {@link SharedModule}.\n */\n@NgModule({\n    imports: [SharedModule, BibliographyRoutingModule],\n    declarations: [\n        routedBibliographyComponents,\n        BibliographySearchComponent,\n        BibliographyListComponent,\n        BibliographyFormatPipe,\n    ],\n    exports: [\n        routedBibliographyComponents,\n        BibliographySearchComponent,\n        BibliographyListComponent,\n        BibliographyFormatPipe,\n    ],\n})\nexport class BibliographyModule {}\n\n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n                   \n    \n         results matching \"\"\n        \n    \n    \n        No results matching \"\"\n    \n\n"},"modules/BibliographyRoutingModule.html":{"url":"modules/BibliographyRoutingModule.html","title":"module - BibliographyRoutingModule","body":"\n                   \n\n\n\n\n    Modules\n    BibliographyRoutingModule\n\n\n\n\n    \n        Info\n    \n    \n        Source\n    \n\n\n\n    \n\n        \n            File\n        \n        \n            src/app/views/data-view/data-outlets/bibliography/bibliography-routing.module.ts\n        \n\n\n\n\n\n        \n            \n            \n        \n\n\n    \n\n\n    \n        import { NgModule } from '@angular/core';\nimport { RouterModule, Routes } from '@angular/router';\n\nimport { BibliographyDetailComponent } from './bibliography-detail/bibliography-detail.component';\nimport { BibliographyComponent } from './bibliography.component';\n\n/* Routes of the BibliographyModule */\nconst BIBLIOGRAPHY_ROUTES: Routes = [\n    {\n        path: '',\n        component: BibliographyComponent,\n        children: [{ path: 'detail/:id', component: BibliographyDetailComponent }],\n    },\n];\n\n/**\n * Routed components of the {@link BibliographyModule}:\n * {@link BibliographyComponent} and {@link BibliographyDetailComponent}.\n */\nexport const routedBibliographyComponents = [BibliographyComponent, BibliographyDetailComponent];\n\n/**\n * Bibliography module routing.\n *\n * It activates the BIBLIOGRAPHY_ROUTES.\n */\n@NgModule({\n    imports: [RouterModule.forChild(BIBLIOGRAPHY_ROUTES)],\n    exports: [RouterModule],\n})\nexport class BibliographyRoutingModule {}\n\n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n                   \n    \n         results matching \"\"\n        \n    \n    \n        No results matching \"\"\n    \n\n"},"components/BibliographySearchComponent.html":{"url":"components/BibliographySearchComponent.html","title":"component - BibliographySearchComponent","body":"\n                   \n\n\n\n\n\n  Components\n  \n  BibliographySearchComponent\n\n\n\n        \n            Info\n        \n        \n            Source\n        \n        \n            Template\n        \n        \n            Styles\n        \n        \n            DOM Tree\n        \n\n\n\n    \n    File\n\n\n    src/app/views/data-view/data-outlets/bibliography/bibliography-search/bibliography-search.component.ts\n\n\n\n    \n        Description\n    \n    \n        The BibliographySearch component.\nIt will contain the search form\nof the bibliography section\nof the search view of the app.\nNot used at the moment.\n\n    \n\n\n\n\n\n    Metadata\n    \n        \n\n\n\n\n\n\n\n\n\n\n\n\n            \n                selector\n                awg-bibliography-search\n            \n\n\n\n            \n                styleUrls\n                ./bibliography-search.component.scss\n            \n\n\n\n            \n                templateUrl\n                ./bibliography-search.component.html\n            \n\n\n\n\n\n\n\n\n        \n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n    \n        import { Component } from '@angular/core';\n\n/**\n * The BibliographySearch component.\n *\n * It will contain the search form\n * of the bibliography section\n * of the search view of the app.\n *\n * Not used at the moment.\n */\n@Component({\n    selector: 'awg-bibliography-search',\n    templateUrl: './bibliography-search.component.html',\n    styleUrls: ['./bibliography-search.component.scss'],\n})\nexport class